#!/usr/bin/env node
// @ts-check
/**
 * Writes the two lists of module code that is bundled at build time (docs/architecture/modules.md,
 * "Off means zero bytes"): the server hooks (`modules/<key>/server.js`) and the staff-app panels
 * (`modules/<key>/staff.js`). The core never imports a module; only these generated files do,
 * so removing a module folder and running this again leaves everything else working (MOD-02).
 *
 *   node tools/modules/registry.js           write the files
 *   node tools/modules/registry.js --check   fail if they are out of date (run by the tests)
 */
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../../', import.meta.url));

export const TARGETS = /** @type {const} */ ([
  {
    out: 'platform/shell/src/server-modules.js',
    file: 'server.js',
    name: 'SERVER_MODULES',
    type: "import('./module-host.js').ServerModule",
    from: '../../../modules',
  },
  {
    out: 'platform/admin/staff-modules.js',
    file: 'staff.js',
    name: 'STAFF_MODULES',
    type: "import('./staff-api.js').StaffModule",
    from: '../../modules',
  },
]);

/** Module keys that have the given file, sorted. */
function keysWith(/** @type {string} */ file) {
  const dir = path.join(root, 'modules');
  return readdirSync(dir, { withFileTypes: true })
    .filter((d) => d.isDirectory() && existsSync(path.join(dir, d.name, file)))
    .map((d) => d.name)
    .sort();
}

/**
 * What the server takes from a module's manifest.
 * @param {string} key
 * @returns {{ needs: string[], events: string[] }}
 */
export function manifestFacts(key) {
  const file = path.join(root, 'modules', key, 'module.json');
  const m = existsSync(file) ? JSON.parse(readFileSync(file, 'utf8')) : {};
  return { needs: m.settings?.needs ?? [], events: m.analyticsEvents ?? [] };
}

/** @param {typeof TARGETS[number]} target */
export function render(target) {
  const keys = keysWith(target.file);
  const staff = target.file === 'staff.js';
  const lines = [
    '// @ts-check',
    '// Generated by tools/modules/registry.js from modules/*/' + target.file + '. Do not edit.',
  ];
  for (const k of keys) {
    lines.push(`import * as ${k} from '${target.from}/${k}/${target.file}';`);
    // The staff app is in French and Arabic; its texts stay out of the customer page.
    if (staff) {
      for (const lang of ['fr', 'ar'])
        lines.push(
          `import ${k}_${lang} from '${target.from}/${k}/i18n/staff.${lang}.json' with { type: 'json' };`,
        );
    }
  }
  const entries = keys.map((k) => {
    if (staff) return `${k}: { ...${k}, texts: { fr: ${k}_fr, ar: ${k}_ar } }`;
    // The server needs two facts from the manifest: settings the module cannot work without,
    // and the analytics events it may count (counts only).
    const { needs, events } = manifestFacts(k);
    const extra = [
      needs.length ? `needs: ${JSON.stringify(needs)}` : '',
      events.length ? `events: ${JSON.stringify(events)}` : '',
    ].filter(Boolean);
    return extra.length ? `${k}: { ...${k}, ${extra.join(', ')} }` : k;
  });
  lines.push(
    '',
    `/** @type {Record<string, ${target.type}>} */`,
    `export const ${target.name} = {${entries.length ? ' ' + entries.join(', ') + ' ' : ''}};`,
    '',
  );
  return lines.join('\n');
}

function run() {
  const check = process.argv.includes('--check');
  let stale = 0;
  for (const target of TARGETS) {
    const file = path.join(root, target.out);
    const want = render(target);
    const have = existsSync(file) ? readFileSync(file, 'utf8') : '';
    if (want === have) continue;
    if (check) {
      process.stderr.write(`${target.out} is out of date: run node tools/modules/registry.js\n`);
      stale++;
    } else {
      writeFileSync(file, want);
      process.stdout.write(`wrote ${target.out}\n`);
    }
  }
  if (stale) process.exitCode = 1;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) run();
